import{_ as t,o as n,c as a,aj as s}from"./chunks/framework.C6uXqnaX.js";const g=JSON.parse('{"title":"End to End Testing","description":"","frontmatter":{},"headers":[],"relativePath":"en/tools/cli/end-to-end.md","filePath":"en/tools/cli/end-to-end.md"}'),i={name:"en/tools/cli/end-to-end.md"};function o(l,e,r,d,p,c){return n(),a("div",null,e[0]||(e[0]=[s(`<h1 id="end-to-end-testing" tabindex="-1">End to End Testing <a class="header-anchor" href="#end-to-end-testing" aria-label="Permalink to &quot;End to End Testing&quot;">​</a></h1><p>End-to-end or (E2E) testing is a form of testing used to assert your entire application works as expected from start to finish or <em>&quot;end-to-end&quot;</em>. E2E testing differs from unit testing in that it is completely decoupled from the underlying implementation details of your code. It is typically used to validate an application in a way that mimics the way a user would interact with it. This page serves as a guide to getting started with end-to-end testing in Angular using the Angular CLI.</p><h2 id="set-up-e2e-testing" tabindex="-1">Set Up E2E Testing <a class="header-anchor" href="#set-up-e2e-testing" aria-label="Permalink to &quot;Set Up E2E Testing&quot;">​</a></h2><p>The Angular CLI downloads and installs everything you need to run end-to-end tests for your Angular application.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e</span></span></code></pre></div><p>The <code>ng e2e</code> command will first check your project for the &quot;e2e&quot; target. If it can&#39;t locate it, the CLI will then prompt you which e2e package you would like to use and walk you through the setup.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>Cannot find &quot;e2e&quot; target for the specified project.</span></span>
<span class="line"><span>You can add a package that implements these capabilities.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For example:</span></span>
<span class="line"><span>Playwright: ng add playwright-ng-schematics</span></span>
<span class="line"><span>Cypress: ng add @cypress/schematic</span></span>
<span class="line"><span>Nightwatch: ng add @nightwatch/schematics</span></span>
<span class="line"><span>WebdriverIO: ng add @wdio/schematics</span></span>
<span class="line"><span>Puppeteer: ng add @puppeteer/ng-schematics</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Would you like to add a package with &quot;e2e&quot; capabilities now?</span></span>
<span class="line"><span>❯ No</span></span>
<span class="line"><span>Playwright</span></span>
<span class="line"><span>Cypress</span></span>
<span class="line"><span>Nightwatch</span></span>
<span class="line"><span>WebdriverIO</span></span>
<span class="line"><span>Puppeteer</span></span></code></pre></div><p>If you don&#39;t find the test runner you would like to use from the list above, you can manually add a package using <code>ng add</code>.</p><h2 id="running-e2e-tests" tabindex="-1">Running E2E Tests <a class="header-anchor" href="#running-e2e-tests" aria-label="Permalink to &quot;Running E2E Tests&quot;">​</a></h2><p>Now that your application is configured for end-to-end testing we can now run the same command to execute your tests.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e</span></span></code></pre></div><p>Note, there isn&#39;t anything &quot;special&quot; about running your tests with any of the integrated e2e packages. The <code>ng e2e</code> command is really just running the <code>e2e</code> builder under the hood. You can always <a href="/en/tools/cli/cli-builder#creating-a-builder">create your own custom builder</a> named <code>e2e</code> and run it using <code>ng e2e</code>.</p><h2 id="more-information-on-end-to-end-testing-tools" tabindex="-1">More information on end-to-end testing tools <a class="header-anchor" href="#more-information-on-end-to-end-testing-tools" aria-label="Permalink to &quot;More information on end-to-end testing tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Testing Tool</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;">Cypress</td><td style="text-align:left;"><a href="https://docs.cypress.io/guides/end-to-end-testing/writing-your-first-end-to-end-test" target="_blank" rel="noreferrer">Getting started with Cypress</a></td></tr><tr><td style="text-align:left;">Nightwatch</td><td style="text-align:left;"><a href="https://nightwatchjs.org/guide/writing-tests/introduction.html" target="_blank" rel="noreferrer">Getting started with Nightwatch</a></td></tr><tr><td style="text-align:left;">WebdriverIO</td><td style="text-align:left;"><a href="https://webdriver.io/docs/gettingstarted" target="_blank" rel="noreferrer">Getting started with Webdriver.io</a></td></tr><tr><td style="text-align:left;">Playwright</td><td style="text-align:left;"><a href="https://playwright.dev/docs/writing-tests" target="_blank" rel="noreferrer">Getting started with Playwright</a></td></tr><tr><td style="text-align:left;">Puppeteer</td><td style="text-align:left;"><a href="https://pptr.dev" target="_blank" rel="noreferrer">Getting started with Puppeteer</a></td></tr></tbody></table>`,14)]))}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
